                for cand in cands:
                    cc = cost(cand)
                    if best is None or cc < bestc:
                        best, bestc = cand, cc
                if bestc + 1e-12 < base:
                    rs[i] = two_opt(best)
                    rs.pop(j)
                    return True
        return False

    for _ in range(12):
        changed = relocate_once(routes)
        routes = [r for r in routes if r]
        changed = merge_once(routes) or changed
        routes = [two_opt(r) for r in routes if r]
        if not changed:
            break

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in cust if seen.get(c, 0) == 0]
    if missing:
        routes.append([])
        for c in missing:
            placed = False
            for r in sorted([rr for rr in routes if rr], key=lambda rr: (load(rr), len(rr), cost(rr))):
                if load(r) + dq(c) <= cap:
                    bestk = 0
                    bestd = None
                    for k in range(len(r) + 1):
                        left = depot if k == 0 else r[k - 1]
                        right = depot if k == len(r) else r[k]
                        dd = dist(left, c) + dist(c, right) - dist(left, right)
                        if bestd is None or dd < bestd:
                            bestd = dd
                            bestk = k
                    r[bestk:bestk] = [c]
                    placed = True
                    break
            if not placed:
                routes.append([c])

    final = []
    seen = set()
    for r in routes:
        nr = []
        ld = 0
        for c in r:
            if c in seen:
                continue
            if ld + dq(c) <= cap:
                nr.append(c)
                seen.add(c)
                ld += dq(c)
        if nr:
            final.append(two_opt(nr))

    for c in cust:
        if c not in seen:
            final.append([c])

    return final
